using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.NativeContinuation.Acquisition;

internal sealed class WindowCanonicalAcquisitionDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Exact canonical acquisition from legal window words.",
        H("Exact canonical acquisition from legal window words"),
        Blocks(
            Paragraph(Text("A single fixed eight-track finite-alphabet program precedes all legal five-window words and independent terminal units with positive original numeral. It reads the actual word, constructs the Horner column and actual height, completes the numeral, and physically produces four canonical registers.")),
            Paragraph(Text("The packed and canonical phases share one attained execution. Time is bounded by an absolute constant times the square of h+1, and the total persistent charge at every prefix by another absolute constant times h+1. The original Horner composition, column sum, growth recurrence and strict Fibonacci capacity are retained. These claims concern input acquisition; three dependent function calls and six output rows require further execution.")),
            Describe.Lean(DescribeId.Create("original-canonical-acquisition"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/WindowCanonicalAcquisition.original_canonical_acquisition"), H("original canonical acquisition"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("With all declared parameters and hypotheses, the exact statement is: original_canonical_acquisition : Function.Injective (finiteCode (\u03b1 := Symbol)) \u2227 \u2203 A B : \u2115, 0 < A \u2227 0 < B \u2227 \u2200 (w : List Window) (e : Bool), D5.S3.Arith.ZeckendorfFutureKernel.legal false (NativeContinuation.NullReplyFiber.highBits (w.map Original.letter) ++ [e]) \u2192 0 < Original.numeral w e \u2192 \u2203 T : \u2115, T \u2264 A*(w.length+1)^2 \u2227 run (initial w e) T = registerEnd w e \u2227 program (registerEnd w e).control = .halt \u2227 RegisterRep (registerEnd w e) 0 (value1 (Original.finalColumns w e)) \u2227 RegisterRep (registerEnd w e) 1 (value2 (Original.finalColumns w e)) \u2227 RegisterRep (registerEnd w e) 2 w.length \u2227 RegisterRep (registerEnd w e) 3 (Original.numeral w e) \u2227 Original.pair (Original.finalColumns w e) = NativeContinuation.JointLaw.composition (w.map Original.letter) \u2227 Original.pair (Original.finalColumns w e) = Original.columnSum w \u2227 Original.maximumColumn [] = 0 \u2227 (\u2200 b, Original.maximumColumn (w ++ [b]) \u2264 5*Original.maximumColumn w+2) \u2227 2*Original.maximumColumn w+1 \u2264 5^w.length \u2227 Original.maximumColumn w \u2264 (5^w.length-1)/2 \u2227 Original.numeral w e < Nat.fib (3*w.length+3) \u2227 (\u2200 n \u2264 T, charged w e n \u2264 B*(w.length+1)) \u2227 (\u2200 n \u2264 T, \u2200 t, 0 \u2264 (run (initial w e) n).head t \u2227 (run (initial w e) n).head t \u2264 3*w.length+6)"))), DescribeRole.Theorem)),
        [DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/WindowRegisterResources"))]));
}
